SEG = 'HIP'
CAT = 'cpbHipaa'
Q = [
("A practice denies a patient's records request on a ground that can be reviewed. Who must do the review?",
 'An uninvolved licensed professional', ["The practice's privacy officer", 'The HHS Office for Civil Rights', "The patient's insurer"],
 'Under 45 CFR 164.524(a)(4), a reviewable denial is reviewed by a licensed health care professional chosen by the covered entity who did not take part in the original decision.'),
("Which cost may be included in the fee for a patient's copy of her records?",
 'Labor for making the copy', ['Time spent searching for the file', 'A records retrieval fee', 'Overhead for the records room'],
 'The reasonable, cost-based fee may cover copying labor, supplies, postage and an agreed summary, not search and retrieval.'),
('A patient asks for her records by unencrypted email. The practice warns her of the risk and she still wants it. What may it do?',
 'Send it as she asked', ['Refuse; email is never allowed', 'Mail paper copies instead', 'Charge a security fee first'],
 'HHS guidance says individuals may receive their PHI by unencrypted email if they ask for it after being warned of the risk.'),
('How long should a signed ABN be kept when no stricter state rule applies?',
 '5 years from the date of care', ['1 year from the date of care', '7 years from the claim date', 'Until the claim is fully paid'],
 'CMS asks notifiers to keep ABNs for 5 years from the date of care delivery when no other state requirement applies.'),
('A practice routinely waives Medicare copays for all patients, regardless of need. Which concern does the OIG raise?',
 'Inducement to beneficiaries', ['Unbundling of the services', 'A Stark designated health service', 'A HIPAA privacy breach'],
 'The OIG warns that routine copay waivers can be inducements under section 1128A(a)(5) and may implicate the False Claims Act.'),
('A physician waives the whole fee for her staff, chosen without regard to referrals. How does the OIG view it?',
 'Likely not a problem', ['An improper beneficiary inducement', 'A Stark Law violation', 'A reportable HIPAA breach'],
 "OIG guidance says regular professional courtesy waiving the entire fee may not implicate its authorities if recipients aren't chosen for referrals."),
('Under OIG compliance guidance for small physician practices, who may serve as the compliance contact?',
 'A staff member with other duties', ['An outside attorney on retainer only', 'A compliance officer the MAC assigns', 'A monitor the OIG appoints'],
 "The OIG's guidance for individual and small group physician practices lets a practice name one person, who may have other duties, as its compliance contact, or share the role among several staff."),
('An internal audit finds a Medicare overpayment. By when must the practice report and return it?',
 'Within 60 days of identifying it', ['By the end of the calendar year', 'Within 12 months of payment', 'Only when the MAC asks'],
 'Section 1128J(d) of the Social Security Act requires an identified overpayment to be reported and returned within 60 days after it is identified.'),
('Who should the practice check against the OIG exclusion list?',
 'Employees and contractors', ['All employees, but not contractors', 'Contractors, but not employees', 'Billing providers only'],
 'Excluded individuals cannot be paid with federal program funds directly or indirectly, so practices screen employees and contractors alike.'),
('Which law forbids a physician referring Medicare patients for designated health services to an entity a family member owns?',
 'Stark Law', ['Anti-Kickback Statute', 'False Claims Act', 'Civil Monetary Penalties Law'],
 'The physician self-referral (Stark) law covers financial relationships of the physician or an immediate family member.'),
('A practice keeps a Medicare overpayment past the 60-day return deadline. Under which law can it become liable?',
 'False Claims Act', ['Anti-Kickback Statute', 'Stark Law', 'HIPAA Privacy Rule'],
 'An overpayment kept after the 60-day deadline is an obligation under the False Claims Act (section 1128J(d)(3)), a so-called reverse false claim.'),
('An Anti-Kickback safe harbor protects an arrangement only if it:',
 'Fits every element of it', ['Is set at fair market value', 'Is in a signed written contract', 'Lasts at least one year'],
 'OIG guidance says a safe harbor protects an arrangement only when it fits every element; fair market value, a signed writing and a one-year term are each only one element of some safe harbors.'),
]
